CREATE TABLE accounts(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,expires_at BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE profiles(user_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,name TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',color TEXT NOT NULL DEFAULT '#ad6142',reduced SMALLINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL);
CREATE TABLE worlds(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES accounts(id),title TEXT NOT NULL,state JSONB NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at BIGINT NOT NULL);
CREATE INDEX worlds_owner ON worlds(owner);
CREATE TABLE members(world_id TEXT NOT NULL REFERENCES worlds(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('gm','player')),last_seen BIGINT NOT NULL,PRIMARY KEY(world_id,user_id));
CREATE INDEX members_user ON members(user_id);
CREATE TABLE events(id TEXT PRIMARY KEY,world_id TEXT NOT NULL REFERENCES worlds(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES accounts(id),name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('roll','chat','system','ping')),visibility TEXT NOT NULL CHECK(visibility IN ('all','gm')),data JSONB NOT NULL,created_at BIGINT NOT NULL);
CREATE INDEX events_world_time ON events(world_id,created_at);
CREATE INDEX events_user_time ON events(user_id,created_at);
CREATE TABLE invites(hash TEXT PRIMARY KEY,world_id TEXT NOT NULL REFERENCES worlds(id) ON DELETE CASCADE,expires_at BIGINT NOT NULL,remaining INTEGER NOT NULL DEFAULT 8 CHECK(remaining>=0));
CREATE TABLE assets(id TEXT PRIMARY KEY,world_id TEXT NOT NULL REFERENCES worlds(id) ON DELETE CASCADE,type TEXT NOT NULL,size INTEGER NOT NULL CHECK(size<=10000000),data BYTEA NOT NULL);
CREATE TABLE auth_attempts(id BIGSERIAL PRIMARY KEY,key TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE INDEX auth_attempts_key_time ON auth_attempts(key,created_at);
